function payrollOperationTariff(value) {
    if (!value.trim())
        return undefined;
    if (!/^\d+(?:[.,]\d{1,2})?$/.test(value.trim()))
        throw new Error('Введите тариф в рублях, не более двух знаков после запятой.');
    const kopecks = Math.round(Number(value.trim().replace(',', '.')) * 100);
    if (!Number.isSafeInteger(kopecks) || kopecks > 2147483647)
        throw new Error('Тариф слишком велик.');
    return kopecks;
}
